inputs = ['hzxjz', 'awf', 'ica', 'gf', 'xa']
outputs = ['hzxjiz', 'aiwf', 'izai', 'vjiwf', 'gi']

# Detailed analysis of each case
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Transform {i}: '{inp}' -> '{outp}'")

    # Look at positions where characters differ
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

    # Check if we're inserting at the end
    if len(outp) > len(inp):
        print(f"  Inserting at end: '{outp[len(inp):]}'")

    # Check if we're replacing a character
    if len(inp) == len(outp):
        # Look for single character replacement
        diff_positions = []
        for j in range(len(inp)):
            if inp[j] != outp[j]:
                diff_positions.append(j)
        if len(diff_positions) == 1:
            print(f"  Single char replacement at position {diff_positions[0]}: '{inp[diff_positions[0]]}' -> '{outp[diff_positions[0]]}'")
    print()

